const COUNT = 60;
const make = (p) => Array.from({ length: COUNT }, (_, i) => ({ label: p + i }));
Noodl.Variables.isl001Rows = make('a');
const delay = Math.floor(Math.random() * 31);
window.__isl001 = { delay, count: COUNT, replaced: false };
setTimeout(() => {
  Noodl.Variables.isl001Rows = make('b');
  window.__isl001.replaced = true;
}, delay);
